@ConfigurationProperties(prefix = "learn-hub")
@Validated
public record LearnHubProperties(
        @NotEmpty List<String> corsOrigins,
        @NotBlank String adminToken,
        @NotBlank @Size(min = 32, message = "JWT 密钥至少 32 字节") String jwtSecret,
        @Min(1) @Max(720) int jwtTtlHours) {

    static final Set<String> DEV_DEFAULTS = Set.of(
            "dev-admin-token",
            "dev-jwt-secret-change-me-at-least-32-bytes");

    public boolean usingDevSecret() {
        return DEV_DEFAULTS.contains(adminToken) || DEV_DEFAULTS.contains(jwtSecret);
    }
}

@Component
class ProdSecretGuard implements ApplicationRunner {

    private final Environment env;
    private final LearnHubProperties props;

    ProdSecretGuard(Environment env, LearnHubProperties props) {
        this.env = env;
        this.props = props;
    }

    @Override
    public void run(ApplicationArguments args) {
        if (env.matchesProfiles("prod") && props.usingDevSecret()) {
            throw new IllegalStateException(
                    "生产环境必须覆盖 LEARNHUB_ADMIN_TOKEN 与 LEARNHUB_JWT_SECRET");
        }
    }
}
